-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Arbeitsschutz > Sicherheitsunterweisung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine Sicherheitsunterweisung für Fachinformatiker in einem IT-Betrieb gesetzlich vorgeschrieben?', 2, '[{"text": "Ja", "correct": true, "because": "ArbSchG § 12 und DGUV-Vorschriften verpflichten dazu"}, {"text": "Nein", "correct": false, "because": "Gesetzlich geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Sicherheitsunterweisung in einem IT-Betrieb regelmäßig wiederholt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Regelmäßige Unterweisung ist Pflicht gemäß ArbSchG"}, {"text": "Nein", "correct": false, "because": "Wiederholung ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Sicherheitsunterweisung Unfälle durch unsachgemäßen Umgang mit IT-Geräten verhindern?', 2, '[{"text": "Ja", "correct": true, "because": "Unterweisung klärt über Risiken auf"}, {"text": "Nein", "correct": false, "because": "Prävention ist ein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Sicherheitsunterweisung in einem IT-Betrieb auch für Homeoffice-Mitarbeiter relevant?', 2, '[{"text": "Ja", "correct": true, "because": "ArbSchG gilt auch für Homeoffice"}, {"text": "Nein", "correct": false, "because": "Umfassend vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Auszubildende in einem IT-Betrieb eine Sicherheitsunterweisung erhalten?', 2, '[{"text": "Ja", "correct": true, "because": "Alle Beschäftigten müssen unterwiesen werden"}, {"text": "Nein", "correct": false, "because": "Pflicht für alle"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz verpflichtet einen IT-Betrieb zur Sicherheitsunterweisung?', 2, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "ArbSchG § 12 regelt Unterweisung"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "GmbHG", "correct": false, "because": "Regelt GmbH"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Sicherheitsunterweisung in einem IT-Betrieb?', 3, '[{"text": "Vermeidung von Arbeitsunfällen", "correct": true, "because": "Prävention ist zentral"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Ziel"}, {"text": "Reduktion der Produktivität", "correct": false, "because": "Produktivität bleibt oder steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Thema sollte eine Sicherheitsunterweisung für Fachinformatiker behandeln?', 3, '[{"text": "Elektrische Sicherheit bei Hardware", "correct": true, "because": "Relevantes Risiko bei IT-Arbeit"}, {"text": "Kundenservice", "correct": false, "because": "Kein Sicherheitsthema"}, {"text": "Wetterbedingungen", "correct": false, "because": "Wenig Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für die Durchführung der Sicherheitsunterweisung in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "ArbSchG legt Verantwortung beim Arbeitgeber"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nicht deren Pflicht"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme folgt typischerweise auf eine Sicherheitsunterweisung in einem IT-Betrieb?', 3, '[{"text": "Umsetzung der erlernten Sicherheitsregeln", "correct": true, "because": "Unterweisung führt zu Praxis"}, {"text": "Erhöhung der Arbeitsbelastung", "correct": false, "because": "Kein Ziel"}, {"text": "Reduzierung der Pausen", "correct": false, "because": "Nicht sicherheitsfördernd"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Themen sollten in einer Sicherheitsunterweisung für Fachinformatiker behandelt werden?', 4, '[{"text": "Elektrische Sicherheit", "correct": true, "because": "Hardware birgt Stromrisiken"}, {"text": "Ergonomische Arbeitsplätze", "correct": true, "because": "Bildschirmarbeit erfordert Ergonomie"}, {"text": "Kundengewinnung", "correct": false, "because": "Kein Sicherheitsthema"}, {"text": "Datensicherheit", "correct": true, "because": "Schutz vor Datenverlust"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Sicherheitsunterweisung einem IT-Betrieb?', 3, '[{"text": "Vermeidung von Arbeitsunfällen", "correct": true, "because": "Prävention ist Ziel"}, {"text": "Erfüllung gesetzlicher Vorgaben", "correct": true, "because": "ArbSchG wird eingehalten"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Vorteil"}, {"text": "Schutz der Mitarbeitergesundheit", "correct": true, "because": "Gesundheit wird gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile kann eine Sicherheitsunterweisung für einen IT-Betrieb haben?', 4, '[{"text": "Zeitaufwand für Schulungen", "correct": true, "because": "Unterweisung braucht Zeit"}, {"text": "Kosten für Durchführung", "correct": true, "because": "Schulungen verursachen Kosten"}, {"text": "Geringere Produktivität", "correct": false, "because": "Produktivität kann langfristig steigen"}, {"text": "Verpflichtung zur Dokumentation", "correct": true, "because": "Nachweis erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln die Sicherheitsunterweisung in einem IT-Betrieb?', 3, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "ArbSchG § 12 regelt Unterweisung"}, {"text": "DGUV-Vorschriften", "correct": true, "because": "Berufsgenossenschaftliche Regeln"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "Bildschirmarbeitsverordnung", "correct": true, "because": "Ergänzt IT-spezifische Vorgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken werden durch Sicherheitsunterweisungen in einem IT-Betrieb minimiert?', 3, '[{"text": "Stromunfälle bei Hardware", "correct": true, "because": "Elektrische Sicherheit"}, {"text": "Ergonomische Schäden", "correct": true, "because": "Bildschirmarbeit"}, {"text": "Geringere Produktivität", "correct": false, "because": "Kein Risiko"}, {"text": "Datenverlust", "correct": true, "because": "Datensicherheitsunterweisung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Sicherheitsunterweisungen sind gesetzlich vorgeschrieben für einen IT-Betrieb. b) Sie müssen nur einmalig durchgeführt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetzlich ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sicherheitsunterweisungen können Unfälle in einem IT-Betrieb verhindern. b) Der Arbeitgeber ist für die Unterweisung verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Unfallprävention und Arbeitgeberpflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Sicherheitsunterweisungen behandeln ergonomische Risiken für Fachinformatiker. b) Sie sind im Homeoffice irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergonomie ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Sicherheitsunterweisungen erhöhen den Verwaltungsaufwand in einem IT-Betrieb. b) Sie schützen die Gesundheit der Mitarbeiter.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Aufwand und Gesundheitsschutz"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Sicherheitsunterweisungen sind für Auszubildende in einem IT-Betrieb Pflicht. b) Sie haben keine gesetzliche Grundlage.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

